7,"ipAddress":7,"email_address":79,"opens_in_new_tab":12},[],{"id":1815,"name":1816,"slug":1817,"type":1122,"position":592,"status":1123,"hidden":7,"published_at":1818,"children":2245,"locked":7},[],{"id":1821,"name":1822,"slug":1823,"type":1122,"position":597,"status":1123,"hidden":7,"published_at":1824,"children":2247,"locked":12},[],["Ref",2249],"townofabingtonma",["Ref",2249],["Ref",2252],["Reactive",1862],["Ref",2254],4538,{"languages":2256,"language":2264,"locale":2265,"componentTranslations":2266},["Ref",2257],["Reactive",2258],[2259,2261],{"language":481,"code":2260},"en",{"language":2262,"code":2263},"Portuguese","pt",["Ref",481],["Ref",2260],["Ref",2267],["Reactive",2268],{"globals":469,"header":479,"floating_nav":487,"footer":489,"menu":501,"live_feed":502,"news":511,"events":515,"programs":518,"athletics":520,"stats":524,"spotlight":2269,"buttons":526,"our_schools":527,"alert_modal":528,"custom_html":529,"pagination":532,"about":468,"sticky_footer":498,"spotlights":525,"custom_component":530,"media_custom_code":531,"video":542},["Reactive",2270],{},{"cmsAiSettings":2272,"clientId":2275,"searchUUID":2276,"sessionId":2277},["Ref",2273],["Reactive",2274],{"ai_chat_enabled":7,"ai_search_enabled":7,"tasks_enabled":7,"display_ai_chat":7},["Ref",2254],["EmptyRef",1941],["EmptyRef",1941],{"alertBannerConfig":2279,"alertBannerSeparate":2283,"isAlertModalOpen":2404},["Ref",2280],["Reactive",2281],{"content":2282,"enabled":7,"light_box":7,"display_on_all_pages":7},"\u003Cp>Massachusetts State Primary Election is today, September 3, 2024. Abington Registered Voters can cast their ballots at Beaver Brook Elementary School at 1 Ralph Hamlin Lane between 7AM - 8PM. \u003C/p>",["Ref",2284],["Reactive",2285],[2286,2293,2298,2303,2308,2313,2318,2323,2328,2334,2339,2343,2348,2353,2358,2363,2368,2373,2378,2383,2388,2393,2398],{"id":2287,"secondary_organization_id":22,"secondary_organization_ids":2288,"content":2289,"image":2290,"status":2291,"style":2292,"display_location":1028,"featured":12},14820,[22],"\u003Cp>In observance of Veterans Day, \u003Cstrong>Abington Town Offices are closed on November 11, 2024\u003C/strong>. Thank you to all those who have served our country.\u003C/p>\u003Cp>Please note, that there is no trash pick up on 11/11/2024, and all routes will be delayed by one day. \u003C/p>",{},"archived","banner",{"id":2294,"secondary_organization_id":22,"secondary_organization_ids":2295,"content":2296,"image":2297,"status":6,"style":2292,"display_location":1028,"featured":12},15997,[22],"\u003Cp>Please note, Abington Town Offices will be closed on Friday, July 4 in recognition of Independence Day.\u003C/p>\u003Cp>There will be no trash collection on \u003Cspan>Friday, July 4. Friday routes will be collected on Saturday, July 5.\u003C/span>\u003C/p>",{"url":79,"alt_text":79},{"id":2299,"secondary_organization_id":22,"secondary_organization_ids":2300,"content":2301,"image":2302,"status":6,"style":2292,"display_location":1028,"featured":12},16843,[22],"\u003Cp>Please note our holiday hours:\u003C/p>\u003Cp>Tuesday, December 31: Open 8:30AM - 12 PM and Wednesday, January 1: Closed.\u003Cbr>\u003Cbr>Trash pick-up is delayed one day for residents with normal pick-ups on Wednesdays, Thursdays, and Fridays.\u003C/p>",{"url":79,"alt_text":79},{"id":2304,"secondary_organization_id":22,"secondary_organization_ids":2305,"content":2306,"image":2307,"status":6,"style":2292,"display_location":1028,"featured":12},17421,[22],"\u003Cp>SPECIAL ELECTION: JANUARY 25, 2024. Polls are open \u003Cspan>9AM - 5PM at Beaver Brook Elementary School located at 1 Ralph G Hamlin Way. \u003C/span>\u003Ca target=\"_self\" rel=\"noopener noreferrer nofollow\" href=\"https://www.abingtonma.gov/o/toa/page/ssvt-building-project\">\u003Cspan>Learn more about the ballot question to allow South Shore Vo Tech to build a new school. \u003C/span>\u003C/a>\u003C/p>",{"url":79,"alt_text":79},{"id":2309,"secondary_organization_id":22,"secondary_organization_ids":2310,"content":2311,"image":2312,"status":6,"style":2292,"display_location":1028,"featured":12},18586,[22],"\u003Cp>The Town of Abington Offices are closed on Monday, January 20, 2025, in recognition of Martin Luther King, Jr., Day. Please note, there will be no trash and recycling collection.\u003C/p>\u003Cp>Monday (1/20) routes will be collected on Tuesday, all other routes will be delayed one day.\u003C/p>",{"url":79,"alt_text":79},{"id":2314,"secondary_organization_id":22,"secondary_organization_ids":2315,"content":2316,"image":2317,"status":6,"style":2292,"display_location":1028,"featured":12},21540,[22],"\u003Cp>In recognition of the Presidents' Day holiday, Abington Town Offices are closed on Monday, February 17, 2025. Trash pick up will be delayed one day for all residents. \u003C/p>",{"url":79,"alt_text":79},{"id":2319,"secondary_organization_id":22,"secondary_organization_ids":2320,"content":2321,"image":2322,"status":6,"style":2292,"display_location":1028,"featured":12},24223,[22],"\u003Cp>Town Offices will be closed on Monday, April 21, 2025 in recognition of Patriots' Day. Trash and recycling will not be picked up on Monday. The scheduled routes will be delayed by one day. \u003C/p>",{"url":79,"alt_text":79},{"id":2324,"secondary_organization_id":22,"secondary_organization_ids":2325,"content":2326,"image":2327,"status":6,"style":2292,"display_location":1028,"featured":12},24282,[22],"\u003Ch3 style=\"text-align: left\">Annual Town Election: Saturday, April 26, 2025. Polls are open at Beaver Brook Elementary School from 8AM -6PM. Early Voting is available at the Town Clerk's office during regular business hours. \u003Ca target=\"_self\" rel=\"noopener noreferrer nofollow\" href=\"https://5il.co/3do3y\">Review a sample ballot.\u003C/a>\u003C/h3>",{"url":79,"alt_text":79},{"id":2329,"secondary_organization_id":22,"secondary_organization_ids":2330,"content":2331,"image":2332,"status":6,"style":2292,"display_location":2333,"featured":12},25028,[22],"\u003Ch2 style=\"text-align: left\">BOIL WATER ORDER LIFTED AS OF MAY 18, 2025.\u003C/h2>\u003Cp style=\"text-align: left\">Customers of Abington/Rockland Joint Water Works were notified on 5/16/2025 of a problem with our drinking water and were advised to boil water prior to consumption. We are pleased to report that the problem has been corrected and that it is no longer necessary to boil water prior to consumption. We apologize for any inconvenience and thank you for your patience. \u003C/p>\u003Cp style=\"text-align: left\">\u003Ca target=\"_blank\" rel=\"noopener noreferrer nofollow\" href=\"https://5il.co/3ggcb\">\u003Cstrong>Read the full notice from ARJWW.\u003C/strong>\u003C/a>\u003C/p>\u003Cp style=\"text-align: left\">\u003C/p>",{"url":79,"alt_text":79},"all_pages",{"id":2335,"secondary_organization_id":22,"secondary_organization_ids":2336,"content":2337,"image":2338,"status":6,"style":2292,"display_location":1028,"featured":12},25311,[22],"\u003Cp>The Town of Abington Offices will be closed on Monday, May 26, 2025 in recognition of Memorial Day. Trash pick-up will be delayed by one day. \u003C/p>",{"url":79,"alt_text":79},{"id":2340,"secondary_organization_id":22,"secondary_organization_ids":2341,"content":2316,"image":2342,"status":1967,"style":2292,"display_location":1028,"featured":12},26147,[22],{"url":79,"alt_text":79},{"id":2344,"secondary_organization_id":22,"secondary_organization_ids":2345,"content":2346,"image":2347,"status":6,"style":2292,"display_location":1028,"featured":12},29933,[22],"\u003Cp>Please note, there are \u003Cstrong>no elections in Abington on Tuesday, November 4, 2025\u003C/strong>. Abington is holding a special election to fill its vacant Select Board seat on Saturday, November 15, 2025. \u003Ca target=\"_self\" rel=\"noopener noreferrer nofollow\" href=\"https://www.abingtonma.gov/article/2510628\">Read more about the Special Election.\u003C/a> \u003C/p>",{"url":79,"alt_text":79},{"id":2349,"secondary_organization_id":22,"secondary_organization_ids":2350,"content":2351,"image":2352,"status":6,"style":2292,"display_location":1028,"featured":12},29934,[22],"\u003Cp>Abington is holding a special election to fill its vacant Select Board seat on Saturday, November 15, 2025. Early/Absentee voting is available. \u003Ca target=\"_self\" rel=\"noopener noreferrer nofollow\" href=\"https://www.abingtonma.gov/article/2510628\">Read more about the special election.\u003C/a>\u003C/p>",{"url":79,"alt_text":79},{"id":2354,"secondary_organization_id":22,"secondary_organization_ids":2355,"content":2356,"image":2357,"status":6,"style":2292,"display_location":1028,"featured":12},30313,[22],"\u003Cp>A Message from the Assessors’ Office:&nbsp;Public Disclosure of FY2026 Proposed Assessed Values&nbsp;Pending Preliminary Certification&nbsp;\u003Ca target=\"_self\" rel=\"noopener noreferrer nofollow\" href=\"https://www.abingtonma.gov/article/2538565\">are now available\u003C/a>.\u003C/p>",{"url":79,"alt_text":79},{"id":2359,"secondary_organization_id":22,"secondary_organization_ids":2360,"content":2361,"image":2362,"status":6,"style":2292,"display_location":1028,"featured":12},30975,[22],"\u003Cp>The Town of Abington offices will be closed on Thursday, November 27 in recognition of the Thanksgiving Holiday. Please note, trash and recycling will not be collected on 11/27. Thursday routes will be collected on Friday, and Friday routes will be collected on Saturday.\u003C/p>",{"url":79,"alt_text":79},{"id":2364,"secondary_organization_id":22,"secondary_organization_ids":2365,"content":2366,"image":2367,"status":6,"style":2292,"display_location":1028,"featured":12},33061,[22],"\u003Cp>\u003Cstrong>Please note Abington Town Hall's holiday schedule:\u003C/strong>\u003C/p>\u003Cp> December 24, 25, and 26: Closed\u003C/p>\u003Cp> December 31: 8:30AM - 12:00PM\u003C/p>\u003Cp>January 1 and 2: Closed\u003C/p>\u003Cp>\u003Cstrong>Property Tax Reminder\u003C/strong>\u003C/p>\u003Cp>Residents who wish to pay their property tax bills before the end of the year must submit payment by 12:00 PM on December 31.\u003C/p>",{"url":79,"alt_text":79},{"id":2369,"secondary_organization_id":22,"secondary_organization_ids":2370,"content":2371,"image":2372,"status":6,"style":2292,"display_location":1028,"featured":12},35687,[22],"\u003Cp>Due to the winter storm earlier this week, trash pick up for all residents is delayed by one day. \u003C/p>",{"url":79,"alt_text":79},{"id":2374,"secondary_organization_id":22,"secondary_organization_ids":2375,"content":2376,"image":2377,"status":6,"style":2292,"display_location":1028,"featured":12},38428,[22],"\u003Cp>🚨 Abington Town Offices, Abington Public Library, and  Senior Center* (normal operations) will be closed on Tuesday, February 24, 2026.\u003C/p>\u003Cp>\u003Cstrong>**Emergency Shelter Update:\u003C/strong>\u003C/p>\u003Cp>The Emergency Shelter at the Senior Center will remain open until 12:00 p.m. on Tuesday, February 24th. Additionally, the Abington Police Department Community Room is available if needed.\u003C/p>\u003Cp>\u003Cstrong>Trash &amp; Recycling Update:\u003C/strong>\u003Cbr>• Monday routes will be picked up next Monday, March 2.\u003Cbr>• Tuesday routes will be picked up on Wednesday, February 25\u003Cbr>• All other routes are delayed one day\u003C/p>\u003Cp>STATE OF EMERGENCY DECLARED – TOWN OF ABINGTON\u003C/p>\u003Cp>\u003Ca target=\"_self\" rel=\"noopener noreferrer nofollow\" href=\"https://www.abingtonma.gov/article/2722324\" relative-link=\"\">Read more about the actions implemented\u003C/a>, including closures, parking bans, and emergency shelter.\u003Cbr>\u003C/p>",{"url":79,"alt_text":79},{"id":2379,"secondary_organization_id":22,"secondary_organization_ids":2380,"content":2381,"image":2382,"status":6,"style":2292,"display_location":1028,"featured":12},44557,[22],"\u003Cp>\u003Cspan>Town Hall will be closed on Friday, July 3rd in observance of July 4th. Friday Trash pick-up will not be affected.\u003C/span>\u003C/p>",{"url":79,"alt_text":79},{"id":2384,"secondary_organization_id":22,"secondary_organization_ids":2385,"content":2386,"image":2387,"status":6,"style":2292,"display_location":1028,"featured":12},44178,[22],"\u003Cp>Town Offices are closed on Friday, June 19, 2026, in observance of the Juneteenth holiday. Town offices will reopen for standard hours on Monday, June 22. Trash will not be collected on Friday, June 19th. Residents with a Friday pick-up day will have a one-day delay and will be collected on Saturday, June 20th.\u003C/p>",{"url":79,"alt_text":79},{"id":2389,"secondary_organization_id":22,"secondary_organization_ids":2390,"content":2391,"image":2392,"status":6,"style":2292,"display_location":1028,"featured":12},45787,[22],"\u003Cp>\u003Cspan>The Massachusetts Department of Environmental Protection has issued a Water Supply Emergency Declaration for the Abington &amp; Rockland Joint Water Works water system. \u003Cstrong>Reservoirs are critically low. \u003C/strong>Mandatory water use restrictions are in place.&nbsp; Please help to conserve water by shutting off irrigation systems and abiding by the Level 4 Water Use Restriction.\u003C/span>\u003C/p>\u003Cp>\u003Cspan>\u003Cbr>\u003Cstrong>Level Four Watering Ban \u003C/strong>- outdoor watering ban. All outdoor water use is prohibited for all uses. \u003C/span>\u003Ca target=\"_self\" rel=\"noopener noreferrer nofollow\" href=\"https://www.abingtonma.gov/article/3053680\">\u003Cspan>Read to learn more. \u003C/span>\u003C/a>\u003C/p>",{"url":79,"alt_text":79},{"id":2394,"secondary_organization_id":22,"secondary_organization_ids":2395,"content":2396,"image":2397,"status":1123,"style":2292,"display_location":1028,"featured":12},47609,[22],"\u003Cp>Effective immediately, the Treasurer/Collector's Office at Town Hall will no longer accept in-person water and sewer bill payments.\u003C/p>\u003Cp>In-person payments must now be dropped off directly at the appropriate office:\u003C/p>\u003Cp>\u003Cstrong>Water bills\u003C/strong> — Joint Water Board Office, 366 Centre Avenue, Rockland\u003Cbr>Hours: Monday–Friday, 8:00 AM–3:30 PM\u003C/p>\u003Cp>\u003Cstrong>Sewer bills\u003C/strong> — Abington Sewer Department, 350 Summer Street, Abington\u003C/p>\u003Cp>Online and mailed payments are not affected and will continue to be processed as usual.\u003C/p>",{"url":79,"alt_text":79},{"id":2399,"secondary_organization_id":22,"secondary_organization_ids":2400,"content":2401,"image":2402,"status":1123,"style":2403,"display_location":1028,"featured":12},48820,[22],"\u003Cp>\u003Ca target=\"_self\" rel=\"noopener noreferrer nofollow\" href=\"https://www.abingtonma.gov/article/3198737\">Early Voting Hours for the November Statewide Election are now available!\u003C/a>\u003C/p>\u003Cp>Sat, Oct 17: 10 AM-4 PM\u003Cbr>Mon, Oct 19: 10 AM-3 PM\u003Cbr>Tue, Oct 20: 10 AM-3 PM\u003Cbr>Wed, Oct 21: 10 AM-3 PM\u003Cbr>Thu, Oct 22: 10 AM-3 PM\u003Cbr>Fri, Oct 23: 9 AM-12 PM\u003Cbr>Sat, Oct 24: 10 AM-4 PM\u003C/p>\u003Cp>Questions? Please call us at 781-982-2112 or email \u003Ca target=\"_blank\" rel=\"noopener noreferrer nofollow\" href=\"mailto:lmadams@abingtonma.gov\">lmadams@abingtonma.gov\u003C/a>. We’re here to help!\u003C/p>",{"url":79,"alt_text":79},"light_box",["EmptyRef",1855],{"hasSections":2406,"pageFilters":2407,"allEvents":2410,"fetchingEvents":2413,"sections":2415,"filters":2418,"selectedCalendars":2421,"selectedFilters":2424,"selectedFilter":2427,"currentView":2430,"listViewType":2432,"currentDate":2434,"calendarViewType":2436,"queryParams":2438,"searchText":2441,"lastFocusedElem":2442,"lastView":2443,"searchTagText":2444,"selectedYearUpdated":2445,"lastActiveEndDate":2446,"totalPastEvents":2447,"totalUpcomingEvents":2449},["EmptyRef",1855],["Ref",2408],["Reactive",2409],[],["Ref",2411],["Reactive",2412],[],["Ref",2414],"INITIAL",["Ref",2416],["Reactive",2417],[],["Ref",2419],["Reactive",2420],[],["Ref",2422],["Reactive",2423],[],["Ref",2425],["Reactive",2426],[],["Ref",2428],["Reactive",2429],[],["Ref",243